/**
 * Error types mirroring the Python exceptions raised by the original program.
 *
 * The reference implementation lets `ValueError`s bubble out of `furl(...)`,
 * which CPython reports on stderr before exiting with a non-zero status.
 */

export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/** Raised by the argparse emulation; the caller turns it into an exit(2). */
export class ArgumentError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentError';
  }
}

