/**
 * Percent-encoding / decoding with the exact semantics of Python's
 * `urllib.parse.quote`, `quote_plus`, `unquote` and `unquote_plus`.
 *
 * The subtleties that matter for byte-for-byte output parity:
 *   - `quote()` always leaves `A-Za-z0-9_.-~` alone, plus whatever is in `safe`.
 *   - Escapes are emitted with upper-case hex digits.
 *   - `unquote()` decodes each maximal run of ASCII characters on its own,
 *     leaving non-ASCII characters untouched, and decodes the recovered bytes
 *     as UTF-8 with U+FFFD replacement (errors='replace').
 *   - A `%` that isn't followed by two hex digits is kept verbatim.
 */

const ALWAYS_SAFE =
  'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-~';

const HEX_DIGITS = '0123456789abcdefABCDEF';

const encoder = new TextEncoder();
// Non-fatal decoding => malformed sequences become U+FFFD, like errors='replace'.
const decoder = new TextDecoder('utf-8');

const safeSetCache = new Map();

function safeBytes(safe) {
  let set = safeSetCache.get(safe);
  if (set === undefined) {
    set = new Set();
    for (const ch of ALWAYS_SAFE + safe) {
      const code = ch.charCodeAt(0);
      if (code < 128) set.add(code);
    }
    safeSetCache.set(safe, set);
  }
  return set;
}

/** Python's `urllib.parse.quote(string, safe)`. */
export function quote(string, safe = '/') {
  const set = safeBytes(safe);
  const bytes = encoder.encode(string);
  let out = '';
  for (const byte of bytes) {
    if (set.has(byte)) {
      out += String.fromCharCode(byte);
    } else {
      out += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return out;
}

/** Python's `urllib.parse.quote_plus(string, safe)`. */
export function quotePlus(string, safe = '') {
  if (!string.includes(' ')) return quote(string, safe);
  return quote(string, safe + ' ').split(' ').join('+');
}

/** Python's `urllib.parse.unquote_to_bytes`, restricted to an ASCII input run. */
function unquoteToBytes(string) {
  const bits = string.split('%');
  const out = [];
  for (const ch of bits[0]) out.push(ch.charCodeAt(0));
  for (let i = 1; i < bits.length; i++) {
    const item = bits[i];
    const hex = item.slice(0, 2);
    if (hex.length === 2 && HEX_DIGITS.includes(hex[0]) && HEX_DIGITS.includes(hex[1])) {
      out.push(parseInt(hex, 16));
      for (const ch of item.slice(2)) out.push(ch.charCodeAt(0));
    } else {
      out.push(0x25); // '%'
      for (const ch of item) out.push(ch.charCodeAt(0));
    }
  }
  return Uint8Array.from(out);
}

/** Python's `urllib.parse.unquote(string)` (utf-8 / errors='replace'). */
export function unquote(string) {
  if (!string.includes('%')) return string;

  let out = '';
  let i = 0;
  while (i < string.length) {
    let j = i;
    while (j < string.length && string.charCodeAt(j) < 0x80) j++;
    if (j > i) out += decoder.decode(unquoteToBytes(string.slice(i, j)));
    i = j;
    let k = i;
    while (k < string.length && string.charCodeAt(k) >= 0x80) k++;
    out += string.slice(i, k);
    i = k;
  }
  return out;
}

/** Python's `urllib.parse.unquote_plus(string)`. */
export function unquotePlus(string) {
  return unquote(string.split('+').join(' '));
}

