/**
 * IDNA (RFC 3490 / IDNA2003) host encoding, as performed by Python's built-in
 * `str.encode('idna')` codec — which is what the reference implementation uses
 * when it renders a host into the final URL string.
 *
 * Only the encoding direction is needed: an all-ASCII label passes straight
 * through, anything else is nameprep'd and then Punycode encoded (RFC 3492)
 * behind the `xn--` ACE prefix.
 */

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;

const ACE_PREFIX = 'xn--';

// IDNA label separators recognised by Python's codec.
const DOTS = /[.。．｡]/;

// StringPrep table B.1 — "commonly mapped to nothing".
const MAPPED_TO_NOTHING = new Set([
  0x00ad, 0x034f, 0x1806, 0x180b, 0x180c, 0x180d, 0x200b, 0x200c, 0x200d,
  0x2060, 0xfe00, 0xfe01, 0xfe02, 0xfe03, 0xfe04, 0xfe05, 0xfe06, 0xfe07,
  0xfe08, 0xfe09, 0xfe0a, 0xfe0b, 0xfe0c, 0xfe0d, 0xfe0e, 0xfe0f, 0xfeff,
]);

function adapt(delta, numpoints, firsttime) {
  delta = firsttime ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  delta += Math.floor(delta / numpoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

function encodeDigit(d) {
  // 0..25 -> 'a'..'z', 26..35 -> '0'..'9'
  return String.fromCharCode(d + 22 + (d < 26 ? 75 : 0));
}

/** RFC 3492 Punycode encoding of a Unicode string. */
export function punycodeEncode(input) {
  const codePoints = Array.from(input).map((c) => c.codePointAt(0));

  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;

  let output = '';
  for (const c of codePoints) if (c < 0x80) output += String.fromCodePoint(c);
  const basicLength = output.length;
  let handled = basicLength;
  if (basicLength > 0) output += '-';

  while (handled < codePoints.length) {
    let m = Infinity;
    for (const c of codePoints) if (c >= n && c < m) m = c;

    delta += (m - n) * (handled + 1);
    n = m;

    for (const c of codePoints) {
      if (c < n) delta++;
      if (c !== n) continue;

      let q = delta;
      for (let k = BASE; ; k += BASE) {
        const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
        if (q < t) break;
        output += encodeDigit(t + ((q - t) % (BASE - t)));
        q = Math.floor((q - t) / (BASE - t));
      }
      output += encodeDigit(q);
      bias = adapt(delta, handled + 1, handled === basicLength);
      delta = 0;
      handled++;
    }

    delta++;
    n++;
  }

  return output;
}

function isAscii(s) {
  for (let i = 0; i < s.length; i++) if (s.charCodeAt(i) > 0x7f) return false;
  return true;
}

/** An approximation of `encodings.idna.nameprep` sufficient for host names. */
function nameprep(label) {
  let mapped = '';
  for (const ch of label) {
    if (MAPPED_TO_NOTHING.has(ch.codePointAt(0))) continue;
    mapped += ch.toLowerCase();
  }
  return mapped.normalize('NFKC');
}

/** `encodings.idna.ToASCII` for a single label. */
function toASCII(label) {
  if (isAscii(label)) return label;

  const prepped = nameprep(label);
  if (isAscii(prepped)) return prepped;

  return ACE_PREFIX + punycodeEncode(prepped);
}

/**
 * Python's `host.encode('idna').decode()`. A trailing label separator is
 * preserved verbatim, matching the codec's own handling of a trailing dot.
 */
export function idnaEncode(host) {
  if (host === null || host === undefined) return host;
  if (isAscii(host)) return host;

  const labels = host.split(DOTS);
  let trailingDot = '';
  if (labels.length > 0 && labels[labels.length - 1] === '') {
    trailingDot = '.';
    labels.pop();
  }
  return labels.map(toASCII).join('.') + trailingDot;
}

