/**
 * A faithful port of the pieces of CPython's `urllib.parse` that the reference
 * implementation depends on: `urlsplit()` and `urlunsplit()`.
 *
 * `urlunsplit()` in particular is what decides whether a `//` shows up in the
 * rendered URL, which is why the `uses_netloc` table has to be reproduced
 * exactly rather than approximated.
 */

import { PyValueError } from './errors.mjs';

const SCHEME_CHARS =
  'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+-.';

const USES_NETLOC = new Set([
  '', 'ftp', 'http', 'gopher', 'nntp', 'telnet', 'imap', 'wais', 'file',
  'mms', 'https', 'shttp', 'snews', 'prospero', 'rtsp', 'rtsps', 'rtspu',
  'rsync', 'svn', 'svn+ssh', 'sftp', 'nfs', 'git', 'git+ssh', 'ws', 'wss',
  'itms-services',
]);

// Characters stripped from the front of a URL (WHATWG C0 control or space).
function lstripC0OrSpace(url) {
  let i = 0;
  while (i < url.length && url.charCodeAt(i) <= 0x20) i++;
  return url.slice(i);
}

function removeUnsafeBytes(url) {
  return url.split('\t').join('').split('\r').join('').split('\n').join('');
}

function isAsciiAlpha(ch) {
  return /^[A-Za-z]$/.test(ch);
}

function splitNetloc(url, start) {
  let delim = url.length;
  for (const c of '/?#') {
    const wdelim = url.indexOf(c, start);
    if (wdelim >= 0 && wdelim < delim) delim = wdelim;
  }
  return [url.slice(start, delim), url.slice(delim)];
}

function isIPv4(host) {
  const parts = host.split('.');
  if (parts.length !== 4) return false;
  return parts.every(
    (p) => /^\d+$/.test(p) && (p === '0' || !p.startsWith('0')) && Number(p) <= 255
  );
}

function isIPv6(host) {
  let address = host;
