  tftp: 69,
  ventrilo: 3784,
  vnc: 5900,
  wais: 210,
  ws: 80,
  wss: 443,
  xmpp: 5222,
};

const INVALID_HOST_CHARS = `!@#$%^&'"*()+=:;/`;

export function defaultPortFor(scheme) {
  if (scheme === null || scheme === undefined) return undefined;
  return Object.prototype.hasOwnProperty.call(DEFAULT_PORTS, scheme)
    ? DEFAULT_PORTS[scheme]
    : undefined;
}

/** Mirrors furl's host setter validation, error message included. */
export function validateHost(host) {
  if (host === null || host === '') return host;

  const bracketed = host.startsWith('[') && host.endsWith(']');
  let valid = bracketed;

  if (!bracketed) {
    valid =
      host.replace(/\./g, '').length > 0 &&
      !host.includes('..') &&
      ![...host].some((ch) => INVALID_HOST_CHARS.includes(ch));
  }

  if (!valid) {
    throw new PyValueError(
      `Invalid host '${host}'. Host strings must have at least one ` +
        `non-period character, can't contain any of '${INVALID_HOST_CHARS}', ` +
        `and can't have adjacent periods.`
    );
  }
  return host;
}

/** Mirrors furl's port setter validation, error message included. */
export function validatePort(port) {
  if (port === null || port === undefined) return null;
  const text = String(port);
  const valid = /^\d+$/.test(text) && Number(text) >= 1 && Number(text) <= 65535;
  if (!valid) throw new PyValueError(`Invalid port '${text}'.`);
  return Number(text);
