  let username = null;
  let password = null;
  let rest = netloc;

  const at = rest.indexOf('@');
  if (at >= 0) {
    const userpass = rest.slice(0, at);
    rest = rest.slice(at + 1);
    const colon = userpass.indexOf(':');
    if (colon >= 0) {
      username = userpass.slice(0, colon);
      password = userpass.slice(colon + 1);
    } else {
      username = userpass;
    }
  }

  let host = rest;
  let port = null;

  const close = rest.lastIndexOf(']');
  const colon = rest.indexOf(':', close + 1) >= 0 ? rest.lastIndexOf(':') : -1;
  if (colon > close) {
    host = rest.slice(0, colon);
    port = validatePort(rest.slice(colon + 1));
  }

  validateHost(host.toLowerCase());
  return { username, password, host: host.toLowerCase(), port };
}

