 *
 * Parsing happens in two steps, exactly like the reference implementation:
 * the scheme is extracted with furl's own permissive rule (anything up to the
 * first ':' that precedes any '/', '?' or '#', provided it starts with an
 * ASCII letter), and only what's left is handed to `urlsplit()`.
 */

import { Fragment, Path, Query } from './components.mjs';
import { defaultPortFor, parseNetloc } from './netloc.mjs';
import { idnaEncode } from './idna.mjs';
import { quote } from './percent.mjs';
import { urlsplit, urlunsplit } from './urlparse.mjs';

function isAsciiAlpha(ch) {
  return ch !== undefined && /^[A-Za-z]$/.test(ch);
}

/** furl's scheme extraction: `''` for a leading ':', `null` when absent. */
export function getScheme(url) {
  if (url.startsWith(':')) return '';

  // A ':' only introduces a scheme when nothing else has started the path,
  // query or fragment yet — otherwise 'a/b:c' would yield the scheme 'a/b'.
  const beforeFragment = url.split('#')[0];
  const beforeQuery = beforeFragment.split('?')[0];
  const beforePath = beforeQuery.split('/')[0];

  const colon = beforePath.indexOf(':');
  if (colon <= 0 || !isAsciiAlpha(url[0])) return null;
  return url.slice(0, colon);
}

/** Remove the leading scheme (and its ':') from a URL string. */
export function stripScheme(url, scheme = getScheme(url)) {
  let rest = url.slice((scheme === null ? '' : scheme).length);
  if (rest.startsWith(':')) rest = rest.slice(1);
  return rest;
}

export class Furl {
  constructor(url = '') {
    this.path = new Path();
    this.query = new Query();
    this.fragment = new Fragment();
    this.load(url);
  }

  load(url) {
    url = url === null || url === undefined ? '' : String(url);

    const rawScheme = getScheme(url);
    const rest = stripScheme(url, rawScheme);

    // Re-parse with a placeholder scheme so that urlsplit() splits the netloc
    // without re-interpreting whatever follows as a scheme of its own.
    const tokens = urlsplit(rawScheme === null ? url : 'http:' + rest);

    this.scheme = rawScheme === null ? null : rawScheme.toLowerCase();

    if (rest.slice(0, 2) === '//') {
      const { username, password, host, port } = parseNetloc(tokens.netloc);
      this.username = username;
      this.password = password;
      this.host = host;
      this.port = port === null ? defaultPortFor(this.scheme) : port;
    } else {
      // No '//' means there is no netloc at all, as opposed to an empty one.
      this.username = null;
      this.password = null;
      this.host = null;
      this.port = defaultPortFor(this.scheme);
    }

    this.path.load(tokens.path);
    this.query.load(tokens.query);
    this.fragment.load(tokens.fragment);
    return this;
  }

  /** `null` when the URL has no netloc, otherwise the rendered netloc. */
  netlocString(useIdna = false) {
    if (this.host === null) return null;

    let userpass = quote(this.username || '', '');
    if (this.password !== null) userpass += ':' + quote(this.password, '');
    if (userpass || this.username !== null) userpass += '@';

    let netloc = useIdna ? idnaEncode(this.host) : this.host;
    if (this.port && this.port !== defaultPortFor(this.scheme)) {
      netloc += ':' + this.port;
    }
    return userpass + netloc;
  }

  get netloc() {
    return this.netlocString(false);
  }

  get url() {
    const netloc = this.netlocString(true);

    let url = urlunsplit(
      this.scheme === null ? '' : this.scheme,
      netloc === null ? '' : netloc,
      this.path.toString(),
      this.query.toString(),
      this.fragment.toString()
    );

    // urlunsplit() can't tell '' apart from None for the scheme and netloc,
    // so those two cases are patched back in afterwards.
    if (this.scheme === '') url = ':' + url;
    if (netloc === '') {
      if (this.scheme === null) url = '//' + url;
      else if (stripScheme(url) === '') url = url + '//';
    }
    return url;
  }

  toString() {
    return this.url;
  }
}

export function furl(url) {
  return new Furl(url);
}

