/**
 * Node.js port of test6.py.
 *
 *   import argparse
 *   from furl import furl
 *   ...
 *   f = furl(args.a)
 *   print(f.scheme); print(f.host); print(f.path)
 *   print(f.query.add({args.b: args.c})); print(f.url)
 */

import { basename } from 'node:path';

import { ArgumentParser } from './lib/argparse.mjs';
import { ArgumentError, PyValueError } from './lib/errors.mjs';
import { furl } from './lib/furl.mjs';

/** Python's `print()` rendering of a value. */
function pyStr(value) {
  if (value === null || value === undefined) return 'None';
  return String(value);
}

function main(argv) {
  const prog = basename(process.argv[1] || 'test6.mjs');
  const parser = new ArgumentParser({ prog });
  parser.addArgument('--a', { required: true });
  parser.addArgument('--b', { required: true });
  parser.addArgument('--c', { required: true });

  let args;
  try {
    const parsed = parser.parseArgs(argv);
    if (parsed.help) {
      process.stdout.write(parser.formatHelp());
      return 0;
    }
    args = parsed.values;
  } catch (err) {
    if (!(err instanceof ArgumentError)) throw err;
    process.stderr.write(parser.formatUsage());
    process.stderr.write(`${prog}: error: ${err.message}\n`);
    return 2;
  }

  let f;
  try {
    f = furl(args.a); // 创建furl对象，解析URL
  } catch (err) {
    if (!(err instanceof PyValueError)) throw err;
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write(`  File "${prog}", line 10, in <module>\n`);
    process.stderr.write('    f = furl(args.a)  # 创建furl对象，解析URL\n');
    process.stderr.write(`ValueError: ${err.message}\n`);
    return 1;
  }

  console.log(pyStr(f.scheme)); // 输出协议
  console.log(pyStr(f.host)); // 输出主机名
  console.log(pyStr(f.path)); // 输出路径
  console.log(pyStr(f.query.add({ [args.b]: args.c }))); // 添加查询参数并输出
  console.log(pyStr(f.url)); // 输出完整URL
  return 0;
}

process.exitCode = main(process.argv.slice(2));

