/**
 * The URL sub-components: Path, Query and Fragment.
 *
 * Each one stores its content *decoded* and re-encodes on demand, which is
 * why `%7E` round-trips to `~` and `%2f` round-trips to `%2F`.
 */

import { quote, quotePlus, unquote, unquotePlus } from './percent.mjs';

/** Characters left unescaped inside a single path segment. */
export const PATH_SAFE_SEGMENT_CHARS = ":@-._~!$&'()*+,;=";

/** A fragment path may additionally hold a literal '?'. */
export const FRAGMENT_PATH_SAFE_SEGMENT_CHARS = PATH_SAFE_SEGMENT_CHARS + '?';

export class Path {
  constructor(safeSegmentChars = PATH_SAFE_SEGMENT_CHARS) {
    this.safeSegmentChars = safeSegmentChars;
    this.segments = [];
  }

  load(path) {
    // Splitting an empty string yields a single empty segment, which encodes
