/**
 * A small stand-in for Python's `argparse.ArgumentParser`, covering the
 * behaviour the original script relies on: required `--name value` options,
 * `--name=value`, `-h/--help`, and argparse's exact error wording and exit
 * codes.
 */

import { ArgumentError } from './errors.mjs';

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    /** @type {Array<{name: string, dest: string, metavar: string, required: boolean}>} */
    this.options = [];
  }

  addArgument(name, { required = false } = {}) {
    const dest = name.replace(/^--?/, '');
    this.options.push({ name, dest, metavar: dest.toUpperCase(), required });
    return this;
  }

  formatUsage() {
    const parts = this.options.map((o) => `${o.name} ${o.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}\n`;
  }

  formatHelp() {
    let help = this.formatUsage();
    help += '\noptions:\n';
    help += '  -h, --help  show this help message and exit\n';
    for (const option of this.options) {
      help += `  ${option.name} ${option.metavar}\n`;
    }
    return help;
  }

  /** Resolve an option string, honouring argparse's unambiguous abbreviations. */
  resolve(prefix) {
    const known = ['-h', '--help', ...this.options.map((o) => o.name)];
    if (known.includes(prefix)) return prefix;
    if (!prefix.startsWith('--')) return null;
    const matches = known.filter((name) => name.startsWith('--') && name.startsWith(prefix));
    return matches.length === 1 ? matches[0] : null;
  }

  /**
   * @returns {{values: Object<string, string>, help: boolean}}
   * @throws {ArgumentError} on any argparse-level failure.
   */
  parseArgs(argv) {
    const values = Object.create(null);
    const extras = [];
    let onlyPositional = false;

    for (let i = 0; i < argv.length; i++) {
      const arg = argv[i];

      if (onlyPositional || !arg.startsWith('-') || arg === '-') {
        extras.push(arg);
        continue;
      }
      if (arg === '--') {
        onlyPositional = true;
        continue;
      }

      const eq = arg.indexOf('=');
      const flag = eq >= 0 ? arg.slice(0, eq) : arg;
      const resolved = this.resolve(flag);

      if (resolved === null) {
        extras.push(arg);
        continue;
      }
      if (resolved === '-h' || resolved === '--help') {
        return { values, help: true };
      }

      const option = this.options.find((o) => o.name === resolved);
      if (eq >= 0) {
        values[option.dest] = arg.slice(eq + 1);
      } else if (i + 1 < argv.length) {
        values[option.dest] = argv[++i];
      } else {
        throw new ArgumentError(`argument ${option.name}: expected one argument`);
      }
    }

    const missing = this.options
      .filter((o) => o.required && values[o.dest] === undefined)
      .map((o) => o.name);
    if (missing.length > 0) {
      throw new ArgumentError(
        `the following arguments are required: ${missing.join(', ')}`
      );
    }
    if (extras.length > 0) {
      throw new ArgumentError(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return { values, help: false };
  }
}

