/**
 * The URL sub-components: Path, Query and Fragment.
 *
 * Each one stores its content *decoded* and re-encodes on demand, which is
 * why `%7E` round-trips to `~` and `%2f` round-trips to `%2F`.
 */

import { quote, quotePlus, unquote, unquotePlus } from './percent.mjs';

/** Characters left unescaped inside a single path segment. */
export const PATH_SAFE_SEGMENT_CHARS = ":@-._~!$&'()*+,;=";

/** A fragment path may additionally hold a literal '?'. */
export const FRAGMENT_PATH_SAFE_SEGMENT_CHARS = PATH_SAFE_SEGMENT_CHARS + '?';

export class Path {
  constructor(safeSegmentChars = PATH_SAFE_SEGMENT_CHARS) {
    this.safeSegmentChars = safeSegmentChars;
    this.segments = [];
  }

  load(path) {
    // Splitting an empty string yields a single empty segment, which encodes
    // back to '' — exactly the round-trip the reference implementation has.
    this.segments = String(path === null || path === undefined ? '' : path)
      .split('/')
      .map(unquote);
    return this;
  }

  toString() {
    return this.segments
      .map((segment) => quote(segment, this.safeSegmentChars))
      .join('/');
  }
}

export class Query {
  constructor() {
    /** @type {Array<[string, string|null]>} */
    this.pairs = [];
  }

  load(query) {
    this.pairs = [];
    const s = query === null || query === undefined ? '' : String(query);
    if (s === '') return this;

    for (const item of s.split('&')) {
      const eq = item.indexOf('=');
      if (eq >= 0) {
        this.pairs.push([unquotePlus(item.slice(0, eq)), unquotePlus(item.slice(eq + 1))]);
      } else {
        this.pairs.push([unquotePlus(item), null]);
      }
    }
    return this;
  }

  /** `Query.add(dict)` — appends the pairs and returns the query itself. */
  add(items) {
    const entries = items instanceof Map ? [...items.entries()] : Object.entries(items);
    for (const [key, value] of entries) {
      this.pairs.push([String(key), value === null || value === undefined ? null : String(value)]);
    }
    return this;
  }

  toString() {
    return this.pairs
      .map(([key, value]) =>
        value === null ? quotePlus(key) : quotePlus(key) + '=' + quotePlus(value)
      )
      .join('&');
  }
}

export class Fragment {
  constructor() {
    this.path = new Path(FRAGMENT_PATH_SAFE_SEGMENT_CHARS);
    this.query = new Query();
    this.separator = false;
  }

  load(fragment) {
    const s = fragment === null || fragment === undefined ? '' : String(fragment);
    const question = s.indexOf('?');

    if (question < 0) {
      // No '?' at all: a path unless it looks like a query, e.g. '#a=a'.
      if (s.includes('=')) {
        this.path.load('');
        this.query.load(s);
      } else {
        this.path.load(s);
        this.query.load('');
      }
      this.separator = false;
    } else if (s.slice(question + 1).includes('=')) {
      // '#path?query' — what follows the '?' really does look like a query.
      this.path.load(s.slice(0, question));
      this.query.load(s.slice(question + 1));
      this.separator = true;
    } else {
      // A bare '?' inside an otherwise path-like fragment, e.g. '#a?b'.
      this.path.load(s);
      this.query.load('');
      this.separator = false;
    }
    return this;
  }

  toString() {
    const path = this.path.toString();
    const query = this.query.toString();
    if (!path && query) return query;
    if (this.separator) return path + '?' + query;
    return path + query;
  }
}

